<x-layouts.app :title="'Track Your Order | '.$shopBrandName">
@php
    $step = in_array($step, ['lookup', 'verify', 'verified_result'], true) ? $step : 'lookup';
    $trackingPayload ??= null;
    $maskEmail = function (?string $email): string {
        if (! $email || ! str_contains($email, '@')) return 'jo••••@example.com';
        [$name, $domain] = explode('@', $email, 2);
        return strlen($name) <= 2
            ? substr($name, 0, 1).'••••@'.$domain
            : substr($name, 0, 2).str_repeat('•', min(strlen($name) - 2, 6)).'@'.$domain;
    };
@endphp
